// U0: the utility-class manifest (generated by tools/metadata/style/gen_utilities.py) is the same as
// data in its ES module and its JSON, and its values are the theme's tokens, never a Tailwind palette.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import test from 'node:test';
import { UTILITIES } from '../src/utilities.generated.js';

const json = JSON.parse(fs.readFileSync(new URL('../src/utilities.generated.json', import.meta.url), 'utf8'));
const completions = JSON.parse(fs.readFileSync(new URL('../src/utilities.completions.generated.json', import.meta.url), 'utf8'));

test('the module and the JSON hold the same manifest', () => {
  assert.deepEqual(UTILITIES, json);
  assert.equal(UTILITIES.schema, 'svelters-utilities/v0');
});

test('values come from the theme tokens', () => {
  const byLabel = new Map(completions.utilities.map((u) => [u.label, u]));
  assert.match(byLabel.get('p-7').detail, /^padding: var\(--sv-space-7\)/);
  assert.match(byLabel.get('bg-surface').detail, /^background-color: var\(--sv-surface\)/);
  assert.ok(!byLabel.has('bg-red-500'), 'no Tailwind palette');
  assert.ok(completions.variants.some((v) => v.label === 'part-indicator:'));
});
